Lemma pcom_end2_spec : forall (q : Z) (ra0 s0' s1' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11' : word)
    ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (F : bvmap 5 word) fc (m : mem),
  sp = Z_to_bv 64 (q + -2240) ->
  rw_cells asegs m (q + -104) (pcom_saved ra0 s0' s1' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11') ->
  2240 <= q < 2^63 -> mem_inv asegs m ->
  evt asegs (pcom_end_post q ra0 gp tp s0' s1' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11' F fc m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x5a074) fc None m (seg_rom asegs)).
